  catalogue: {"note":"The measurements ByteMe offers. One shared list: the website (app.js) and the Python scripts (build_world.py, tests) both read it. 'code' is the NASA POWER parameter name. 'scale' multiplies the raw value (soil wetness 0-1 becomes percent). 'percent' says whether a percent change makes sense (zero means 'none of it').","groups":["Temperature","Water","Land","Air","Sun and sky"],"variables":[{"code":"T2M","name":"Air temperature","units":"\u00b0C","group":"Temperature","source":"MERRA-2","percent":false,"definition":"How warm the air is 2 metres above the ground, averaged over day and night.","keywords":"temperature hot hotter warm warmer warming cold colder cooling heat climate"},{"code":"T2M_MAX","name":"Hottest temperature of the month","units":"\u00b0C","group":"Temperature","source":"MERRA-2","percent":false,"definition":"The highest air temperature reached during each month.","keywords":"maximum hottest heatwave heatwaves extreme peak highs"},{"code":"T2M_MIN","name":"Coldest temperature of the month","units":"\u00b0C","group":"Temperature","source":"MERRA-2","percent":false,"definition":"The lowest air temperature reached during each month.","keywords":"minimum coldest frost freeze freezing nights lows winter winters"},{"code":"TS","name":"Surface temperature","units":"\u00b0C","group":"Temperature","source":"MERRA-2","percent":false,"definition":"How warm the ground or the sea surface itself is (its 'skin').","keywords":"surface skin ground sea ocean water temperature"},{"code":"PRECTOTCORR","name":"Rain and snowfall","units":"mm/day","group":"Water","source":"MERRA-2","percent":true,"definition":"How much rain and snow fall each day on average.","keywords":"rain rains raining rainfall rainy precipitation downpour wet wetter drought monsoon storms flood floods"},{"code":"EVLAND","name":"Evaporation from land","units":"mm/day","group":"Water","source":"MERRA-2","percent":true,"definition":"How much water moves from the ground and plants into the air each day. Land only.","keywords":"evaporation evaporate evaporates evaporating evapotranspiration"},{"code":"RH2M","name":"Relative humidity","units":"%","group":"Water","source":"MERRA-2","percent":false,"definition":"How close the air is to holding all the water vapour it can (100% = saturated).","keywords":"humidity humid muggy damp relative"},{"code":"QV2M","name":"Water vapour in the air","units":"g/kg","group":"Water","source":"MERRA-2","percent":true,"definition":"Grams of water vapour in each kilogram of air near the ground.","keywords":"vapour vapor moisture specific humidity"},{"code":"PW","name":"Water in the whole air column","units":"cm","group":"Water","source":"MERRA-2","percent":true,"definition":"If all the water vapour above you fell as rain at once, how deep the layer would be.","keywords":"precipitable column atmosphere water"},{"code":"GWETTOP","name":"Surface soil wetness","units":"%","scale":100,"group":"Land","source":"MERRA-2","percent":false,"definition":"How wet the top 5 cm of soil is: 0% is completely dry, 100% is fully soaked.","keywords":"soil topsoil surface wetness dry drier drying dust dirt"},{"code":"GWETROOT","name":"Root-zone soil wetness","units":"%","scale":100,"group":"Land","source":"MERRA-2","percent":false,"definition":"How wet the soil is where plant roots grow (top metre): 0% dry, 100% soaked. Land only.","keywords":"soil moisture roots root dry drier drying drought crops farming farmland agriculture desert"},{"code":"SNODP","name":"Snow depth","units":"cm","group":"Land","source":"MERRA-2","percent":true,"definition":"How deep the snow lying on the ground is. Land only.","keywords":"snow snowy snowpack ski glacier ice melting melt"},{"code":"WS10M","name":"Wind speed","units":"m/s","group":"Air","source":"MERRA-2","percent":true,"definition":"How fast the air moves 10 metres above the ground.","keywords":"wind winds windy windier breeze gust storm"},{"code":"PS","name":"Air pressure","units":"kPa","group":"Air","source":"MERRA-2","percent":false,"definition":"The weight of the air above pressing on the surface.","keywords":"pressure barometer barometric"},{"code":"TO3","name":"Ozone layer","units":"DU","group":"Air","source":"MERRA-2","percent":false,"definition":"The total amount of ozone above you, in Dobson units. Ozone high up shields life from UV light.","keywords":"ozone hole layer uv ultraviolet"},{"code":"AOD_55","name":"Haze and dust in the air","units":"AOD","group":"Air","source":"MERRA-2","percent":true,"definition":"How much tiny particles (dust, smoke, pollution) dim the sunlight. 0 is perfectly clear air; above 0.4 is hazy.","keywords":"aerosol aerosols haze hazy dust dusty smoke smog pollution polluted air quality particles wildfire"},{"code":"ALLSKY_SFC_SW_DWN","name":"Sunlight reaching the ground","units":"MJ/m\u00b2/day","group":"Sun and sky","source":"CERES","percent":true,"definition":"The energy of the sunlight that arrives at the surface each day, clouds included.","keywords":"sun sunny sunnier sunlight sunshine solar radiation light energy brightness dimming"},{"code":"CLOUD_AMT","name":"Cloud cover","units":"%","group":"Sun and sky","source":"CERES","percent":false,"definition":"The share of the sky covered by clouds.","keywords":"cloud clouds cloudy cloudier cloudiness overcast sky"}]},
